class HostAdapterError(ValueError):
    """One explicit adapter request could not be converted or completed."""

    def __init__(self, code: str, message: str, *, details: Any = None) -> None:
        super().__init__(message)
        self.code = code
        self.details = details


def _adapter_use_case(function: Any) -> Any:
    @wraps(function)
    def wrapped(*args: Any, **kwargs: Any) -> Any:
        try:
            with args[0].coordinator.read_operation():
                return function(*args, **kwargs)
        except ApplicationCoordinatorError as error:
            raise HostAdapterError(
                error.code,
                str(error),
                details=error.details,
            ) from error
        except RecordReadingError as error:
            raise HostAdapterError(error.code, str(error)) from error

    return wrapped


def _required_text(value: Any, field: str) -> str:
    if not isinstance(value, str) or not value.strip():

def _command_errors(
    function: Callable[P, R],
) -> Callable[P, R | None]:
    @wraps(function)
    def wrapped(*args: P.args, **kwargs: P.kwargs) -> R | None:
        try:
            return function(*args, **kwargs)
        except (
            ApplicationCoordinatorError,
            HostAdapterError,
            MaintenanceError,
            OSError,
        ) as error:
            code = getattr(error, "code", "local_io_failed" if isinstance(error, OSError) else "application_use_case_rejected")
            details = getattr(error, "issues", None) or getattr(
                error,
                "details",
                None,
            )
            error_payload: dict[str, Any] = {
                "code": code,
                "message": str(error),
            }
            if details:
                error_payload["details"] = (
                    list(details)
                    if isinstance(details, (list, tuple))
                    else details
                )
            _emit(
                {
                    "ok": False,
                    "error": error_payload,
                }
            )
            raise click.exceptions.Exit(1) from None

    return wrapped

